scripts.onboarding-store:
import { type InferredInput, defineScript, gezel } from '@bendyline/gezel-sdk';
import { rosterStore } from '@bendyline/gezel-sdk/stores';

export const meta = defineScript({
  name: 'onboarding-store',
  description:
    "Read and update the onboarding plans: hires.json (each new hire, their start date, manager and buddy) and tasks.json (every step of every plan, with a phase, an owner and a due date). action:'status' for open steps due soon (overdue first) and each hire's progress; 'add_hire' to add a hire with the standard plan (an existing name is updated, never duplicated); 'add_task' to add a step to a plan; 'complete' to check steps off; 'list' for whole plans.",
  inputs: {
    action: { type: 'string', description: "One of 'status', 'add_hire', 'add_task', 'complete', or 'list'.", required: true },
    name: { type: 'string', description: "For add_hire: the new hire's full name." },
    role: { type: 'string', description: "For add_hire: their job, e.g. 'Barista'." },
    startOn: { type: 'string', description: "For add_hire: their first day, YYYY-MM-DD or a weekday like 'monday'." },
    manager: { type: 'string', description: 'For add_hire: their manager.' },
    buddy: { type: 'string', description: 'For add_hire: the teammate who shows them around the first week.' },
    hire: { type: 'string', description: "Hire id (e.g. 'h-2') or name; a first name is enough when it is unique." },
    title: { type: 'string', description: 'For add_task: what needs doing.' },
    phase: {
      type: 'string',
      description: "before day one, day one, first week, 30 days, 60 days, or 90 days. For complete: checks off every open step in that phase.",
    },
    owner: { type: 'string', description: 'For add_task: who does it.' },
    dueOn: { type: 'string', description: 'For add_task: the due date, YYYY-MM-DD; default the phase’s usual day.' },
    task: { type: 'string', description: "For complete: a step's id (e.g. 't-4') or words from its title; several separated by commas." },
    reopen: { type: 'boolean', description: 'For complete: put a checked step back on the list.' },
    note: { type: 'string', description: 'What happened.' },
    withinDays: { type: 'number', description: 'How many days ahead count as due soon (default 7).' },
  },
  outputs: {
    active: { type: 'number', description: 'Hires still onboarding.' },
    overdue: { type: 'number', description: 'Open steps past their due date.' },
    dueSoon: { type: 'number', description: 'Open steps due within the window.' },
    summary: { type: 'string', description: 'What changed, then the onboarding picture or the listing.' },
  },
  requires: ['workspace.read', 'workspace.write'],
} as const);

const input = gezel.input as InferredInput<typeof meta>;

// ── onboarding-rules-start ──
// Pure derivations: dates in local calendar days, record matching, the
// standard plan, phase names, task matching, and the picture the crew reads.
// Kept self-contained between these sentinels so tests execute the shipped
// bytes.
var DAY_MS = 86400000;
var WEEKDAYS = ['Sunday', 'Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday'];
var MONTH_KEYS = ['jan', 'feb', 'mar', 'apr', 'may', 'jun', 'jul', 'aug', 'sep', 'oct', 'nov', 'dec'];

function pad(n) {
  return n < 10 ? '0' + n : String(n);
}
function localDay(ms) {
  var d = new Date(ms);
  return d.getFullYear() + '-' + pad(d.getMonth() + 1) + '-' + pad(d.getDate());
}
function noon(day) {
  return new Date(String(day).slice(0, 10) + 'T12:00:00');
}
function addDays(day, n) {
  var d = noon(day);
  d.setDate(d.getDate() + n);
  return localDay(d.getTime());
}
function addMonths(day, months) {
  var d = noon(day);
  var date = d.getDate();
  d.setDate(1);
  d.setMonth(d.getMonth() + months);
  // The 31st rolls to the last day of a shorter month, not into the next one.
  d.setDate(Math.min(date, new Date(d.getFullYear(), d.getMonth() + 1, 0).getDate()));
  return localDay(d.getTime());
}
function daysLeft(day, nowMs) {
  var due = Date.parse(String(day).slice(0, 10) + 'T00:00:00');
  var today = Date.parse(localDay(nowMs) + 'T00:00:00');
  return Math.round((due - today) / DAY_MS);
}
function dayName(day) {
  return WEEKDAYS[noon(day).getDay()];
}
function parseDay(text, nowMs, direction) {
  var raw = String(text == null ? '' : text).trim().toLowerCase().replace(/[.,]/g, ' ').replace(/\s+/g, ' ').trim();
  if (!raw) return null;
  var iso = raw.match(/^(\d{4})-(\d{1,2})-(\d{1,2})(?:t.*)?$/);
  if (iso) return iso[1] + '-' + pad(Number(iso[2])) + '-' + pad(Number(iso[3]));
  var today = localDay(nowMs);
  if (raw === 'today' || raw === 'now') return today;
  if (raw === 'tomorrow') return addDays(today, 1);
  if (raw === 'yesterday') return addDays(today, -1);
  var rel = raw.match(/^(?:in )?(\d{1,3}) (day|days|week|weeks)( ago| from now)?$/);
  if (rel) {
    var n = Number(rel[1]) * (rel[2].charAt(0) === 'w' ? 7 : 1);
    return addDays(today, rel[3] === ' ago' ? -n : n);
  }
  var wd = raw.match(/^(this |next |last |on |coming )?(sun|mon|tue|wed|thu|fri|sat)[a-z]*$/);
  if (wd) {
    var target = ['sun', 'mon', 'tue', 'wed', 'thu', 'fri', 'sat'].indexOf(wd[2]);
    var now = noon(today).getDay();
    if (direction === 'past' || wd[1] === 'last ') {
      var back = (now - target + 7) % 7;
      return addDays(today, -(wd[1] === 'last ' && back === 0 ? 7 : back));
    }
    if (wd[1] === 'this ') return addDays(today, (target - now + 7) % 7);
    return addDays(today, ((target - now + 6) % 7) + 1);
  }
  var md = raw.match(/^(?:[a-z]+day )?([a-z]{3,9}) (\d{1,2})(?:st|nd|rd|th)?(?: (\d{4}))?$/);
  var dm = raw.match(/^(?:[a-z]+day )?(\d{1,2})(?:st|nd|rd|th)? (?:of )?([a-z]{3,9})(?: (\d{4}))?$/);
  var parts = md ? { month: md[1], date: md[2], year: md[3] } : dm ? { month: dm[2], date: dm[1], year: dm[3] } : null;
  if (parts) {
    var m = MONTH_KEYS.indexOf(parts.month.slice(0, 3));
    if (m < 0) return null;
    var date = Number(parts.date);
    if (date < 1 || date > 31) return null;
    if (parts.year) return parts.year + '-' + pad(m + 1) + '-' + pad(date);
    var year = noon(today).getFullYear();
    var guess = year + '-' + pad(m + 1) + '-' + pad(date);
    var d = daysLeft(guess, nowMs);
    if (direction === 'past' && d > 0) guess = year - 1 + guess.slice(4);
    if (direction !== 'past' && d < 0) guess = year + 1 + guess.slice(4);
    return guess;
  }
  return null;
}
function matches(records, text, labelOf) {
  var wanted = String(text == null ? '' : text).trim().toLowerCase().replace(/['\u2019]s\b/g, '').replace(/\s+/g, ' ');
  if (!wanted) return [];
  var tiers = [
    function (r) { return String(r.id).toLowerCase() === wanted; },
    function (r) { return labelOf(r).toLowerCase() === wanted; },
    function (r) { return labelOf(r).toLowerCase().indexOf(wanted) === 0; },
    function (r) { return (' ' + labelOf(r).toLowerCase() + ' ').indexOf(' ' + wanted + ' ') >= 0; },
    function (r) { return labelOf(r).toLowerCase().indexOf(wanted) >= 0; },
    function (r) { var l = labelOf(r).toLowerCase(); return l.length >= 3 && wanted.indexOf(l) >= 0; },
  ];
  for (var i = 0; i < tiers.length; i++) {
    var hit = records.filter(tiers[i]);
    if (hit.length) return hit;
  }
  return [];
}
function describe(records, labelOf) {
  return records.map(function (r) { return r.id + ' ' + labelOf(r); }).join(', ');
}
function splitList(text) {
  var raw = String(text == null ? '' : text).trim();
  if (/^\[/.test(raw)) {
    try {
      var parsed = JSON.parse(raw);
      if (Array.isArray(parsed)) return parsed.map(function (s) { return String(s).trim(); }).filter(Boolean);
    } catch (e) {
      // Not JSON after all; split it as text.
    }
  }
  return raw
    .split(/\s*[,;\n]+\s*/)
    .map(function (s) { return s.replace(/^(and|or|plus)\s+/i, '').replace(/[.\s]+$/, '').trim(); })
    .filter(Boolean);
}
var PHASES = ['before day one', 'day one', 'first week', '30 days', '60 days', '90 days'];
var PHASE_OFFSET = { 'before day one': -2, 'day one': 0, 'first week': 4, '30 days': 30, '60 days': 60, '90 days': 90 };
// The standard plan every new hire starts with; offsets are days from the first day.
var PLAN = [
  ['before day one', 'Send a welcome note with the start time, place and what to bring', 'manager', -5],
  ['before day one', 'Set up email and scheduling accounts', 'office', -3],
  ['before day one', 'Prepare uniform, keys and workspace', 'office', -2],
  ['before day one', 'Collect tax, payroll and emergency-contact forms', 'office', -1],
  ['day one', 'Tour, introductions and safety basics', 'manager', 0],
  ['day one', 'Pair with a buddy for the first week', 'manager', 0],
  ['first week', 'Shadow shifts with the buddy', 'buddy', 3],
  ['first week', 'Enroll in the training the role needs', 'training', 4],
  ['first week', 'First-week check-in', 'manager', 5],
  ['30 days', '30-day check-in: what is going well, what is unclear', 'manager', 30],
  ['30 days', 'Required certificates on file', 'training', 30],
  ['60 days', '60-day check-in', 'manager', 60],
  ['90 days', '90-day review and goals for the next quarter', 'manager', 90],
];
var TASK_STOP = ['with', 'from', 'that', 'this', 'have', 'done', 'were', 'they', 'their', 'into', 'about', 'what'];

function ownerFor(kind, hire) {
  var f = (hire && hire.fields) || {};
  if (kind === 'manager') return f.manager || 'Manager';
  if (kind === 'buddy') return f.buddy || 'Buddy';
  if (kind === 'office') return 'Office';
  if (kind === 'training') return 'Training';
  return String(kind || '');
}
function planFor(hire) {
  return PLAN.map(function (p) {
    return { phase: p[0], title: p[1], ownerKind: p[2], owner: ownerFor(p[2], hire), offset: p[3], dueAt: addDays(hire.fields.startOn, p[3]) };
  });
}
function phaseOf(text) {
  var raw = String(text == null ? '' : text).trim().toLowerCase();
  if (!raw) return null;
  if (PHASES.indexOf(raw) >= 0) return raw;
  if (/before|prior|ahead|pre-?start|preboard/.test(raw)) return 'before day one';
  if (/\b(day (one|1)|first day|start day|day of)\b/.test(raw)) return 'day one';
  if (/\b(first|1st) week\b|\bweek (one|1)\b|^week$/.test(raw)) return 'first week';
  if (/\b(30|thirty)\b|first month|one month/.test(raw)) return '30 days';
  if (/\b(60|sixty)\b|two months/.test(raw)) return '60 days';
  if (/\b(90|ninety)\b|three months/.test(raw)) return '90 days';
  return null;
}
function keyWords(text) {
  return (String(text == null ? '' : text).toLowerCase().match(/[a-z0-9]+/g) || [])
    .filter(function (w) { return w.length >= 4 && TASK_STOP.indexOf(w) < 0; })
    .map(function (w) { return w.length > 4 ? w.replace(/s$/, '') : w; });
}
function taskMatches(tasks, text) {
  var hit = matches(tasks, text, function (t) { return String(t.fields.title || ''); });
  if (hit.length) return hit;
  var want = keyWords(text);
  if (!want.length) return [];
  var best = [];
  var score = 0;
  tasks.forEach(function (t) {
    var have = keyWords(t.fields.title);
    var s = want.filter(function (w) { return have.indexOf(w) >= 0; }).length;
    if (s > score) {
      best = [t];
      score = s;
    } else if (s === score && s > 0) best.push(t);
  });
  return score >= Math.min(2, want.length) ? best : [];
}
function whenText(day, nowMs) {
  var d = daysLeft(day, nowMs);
  return d < 0 ? -d + (d === -1 ? ' day late' : ' days late') : d === 0 ? 'due today' : d === 1 ? 'due tomorrow' : 'due ' + dayName(day) + ' ' + day;
}
function startText(hire, nowMs) {
  var d = daysLeft(hire.fields.startOn, nowMs);
  return d > 0 ? 'starts ' + dayName(hire.fields.startOn) + ' ' + hire.fields.startOn + ', in ' + d + (d === 1 ? ' day' : ' days') : d === 0 ? 'starts today' : 'day ' + (1 - d) + ', started ' + hire.fields.startOn;
}
function taskLine(t, nowMs) {
  return t.fields.title + ' (' + t.id + ', ' + (t.fields.owner || 'no owner') + ', ' + whenText(t.fields.dueAt, nowMs) + ')';
}
function picture(hires, tasks, nowMs, withinDays) {
  var active = hires.filter(function (h) { return h.status !== 'done'; }).sort(function (a, b) { return String(a.fields.startOn).localeCompare(String(b.fields.startOn)); });
  var byDue = function (a, b) { return String(a.fields.dueAt).localeCompare(String(b.fields.dueAt)); };
  var open = tasks.filter(function (t) { return t.status !== 'done' && active.some(function (h) { return h.id === t.fields.hireId; }); });
  var overdue = open.filter(function (t) { return daysLeft(t.fields.dueAt, nowMs) < 0; }).sort(byDue);
  var soon = open.filter(function (t) { var d = daysLeft(t.fields.dueAt, nowMs); return d >= 0 && d <= withinDays; }).sort(byDue);
  var parts = [active.length + (active.length === 1 ? ' new hire' : ' new hires') + ' onboarding, ' + overdue.length + (overdue.length === 1 ? ' step' : ' steps') + ' overdue.'];
  // One list, overdue first: "what's due this week" and "what's overdue" are both answered from it.
  var due = overdue.concat(soon);
  parts.push(
    due.length
      ? 'Open steps due within ' + withinDays + ' days, overdue first: ' + due.map(function (t) { return t.fields.hireName + ': ' + taskLine(t, nowMs); }).join(' | ') + '.'
      : 'Nothing due in the next ' + withinDays + ' days.',
  );
  active.forEach(function (h) {
    var mine = tasks.filter(function (t) { return t.fields.hireId === h.id; });
    var left = mine.filter(function (t) { return t.status !== 'done'; }).sort(byDue);
    var before = daysLeft(h.fields.startOn, nowMs) > 0 ? left.filter(function (t) { return t.fields.phase === 'before day one'; }) : [];
    parts.push(
      h.fields.name + ' (' + h.id + ', ' + (h.fields.role || 'no role') + ', ' + startText(h, nowMs) +
        (h.fields.manager ? ', manager ' + h.fields.manager : '') + (h.fields.buddy ? ', buddy ' + h.fields.buddy : '') + '): ' +
        (mine.length - left.length) + ' of ' + mine.length + ' steps done' +
        (before.length ? '; still to do before day one: ' + before.map(function (t) { return taskLine(t, nowMs); }).join('; ') : left.length ? '; next: ' + taskLine(left[0], nowMs) : '') + '.',
    );
  });
  return { active: active.length, overdue: overdue.length, dueSoon: soon.length, summary: parts.join(' ') };
}
// ── onboarding-rules-end ──

const hires = rosterStore(gezel.fs, 'hires.json', { stages: ['active', 'done'], idPrefix: 'h' });
const tasks = rosterStore(gezel.fs, 'tasks.json', { stages: ['todo', 'done'], idPrefix: 't' });
const now = Date.now();
const withinDays = typeof input.withinDays === 'number' && input.withinDays > 0 ? Math.round(input.withinDays) : 7;
const nameOf = (r: { fields: Record<string, unknown> }) => String(r.fields.name ?? '');
const titleOf = (r: { fields: Record<string, unknown> }) => String(r.fields.title ?? '');

async function resolveHire(text?: string) {
  const all = await hires.list();
  if (!text) {
    const active = all.filter((h) => h.status !== 'done');
    if (active.length === 1) return active[0]!;
    throw new Error("Pass 'hire' (id or name). New hires: " + (describe(all, nameOf) || 'none yet; add one with add_hire') + '.');
  }
  let hits = matches(all.filter((h) => h.status !== 'done'), text, nameOf);
  if (!hits.length) hits = matches(all, text, nameOf);
  if (hits.length === 1) return hits[0]!;
  if (hits.length > 1) throw new Error("More than one hire matches '" + text + "': " + describe(hits, nameOf) + '. Pass the id.');
  throw new Error("No new hire matches '" + text + "'. New hires: " + (describe(all, nameOf) || 'none yet; add one with add_hire') + '.');
}

// A plan whose every step is checked off is finished; a new or reopened step puts it back.
async function settle(hireId: string): Promise<string> {
  const hire = await hires.get(hireId);
  if (!hire) return '';
  const mine = (await tasks.list()).filter((t) => t.fields.hireId === hireId);
  const left = mine.filter((t) => t.status !== 'done').length;
  if (!left && mine.length && hire.status !== 'done') {
    await hires.transition(hireId, 'done', { note: 'Every step done' });
    return ' ' + nameOf(hire) + "'s plan is complete.";
  }
  if (left && hire.status === 'done') await hires.transition(hireId, 'active');
  return '';
}

let note = '';

if (input.action === 'add_hire') {
  if (!input.name || !input.name.trim()) throw new Error("add_hire needs 'name'.");
  const name = input.name.trim();
  const startOn = input.startOn ? parseDay(input.startOn, now, 'future') : null;
  if (input.startOn && !startOn) throw new Error("startOn must be a date like '2026-11-09' or a weekday like 'monday'.");
  const fields: Record<string, unknown> = {
    ...(input.role ? { role: input.role.trim() } : {}),
    ...(startOn ? { startOn } : {}),
    ...(input.manager ? { manager: input.manager.trim() } : {}),
    ...(input.buddy ? { buddy: input.buddy.trim() } : {}),
    ...(input.note ? { notes: input.note.trim() } : {}),
  };
  const existing = (await hires.list()).find((h) => nameOf(h).toLowerCase() === name.toLowerCase());
  if (existing) {
    const updated = await hires.update(existing.id, { fields });
    // A moved start date or a named manager/buddy carries into the open standard steps.
    let moved = 0;
    for (const t of (await tasks.list()).filter((x) => x.fields.hireId === existing.id && x.status !== 'done')) {
      const patch: Record<string, unknown> = {};
      if (typeof t.fields.offset === 'number' && startOn && startOn !== existing.fields.startOn) patch.dueAt = addDays(startOn, t.fields.offset);
      if (t.fields.ownerKind && (input.manager || input.buddy)) patch.owner = ownerFor(t.fields.ownerKind, updated);
      if (Object.keys(patch).length) {
        await tasks.update(t.id, { fields: patch });
        if (patch.dueAt) moved += 1;
      }
    }
    note = 'Updated ' + name + ' (' + existing.id + ')' + (moved ? '; moved ' + moved + ' open steps to the new start date.' : '.');
  } else {
    if (!startOn) throw new Error("A new hire needs 'startOn', their first day (YYYY-MM-DD or a weekday).");
    const hire = await hires.add({ status: 'active', fields: { name, role: '', ...fields } });
    for (const step of planFor(hire)) {
      await tasks.add({
        status: 'todo',
        fields: {
          hireId: hire.id,
          hireName: name,
          title: step.title,
          phase: step.phase,
          owner: step.owner,
          ownerKind: step.ownerKind,
          offset: step.offset,
          dueAt: step.dueAt,
        },
      });
    }
    note = 'Added ' + name + ' (' + hire.id + '), first day ' + dayName(startOn) + ' ' + startOn + ', with the standard ' + PLAN.length + '-step plan.';
  }
} else if (input.action === 'add_task') {
  if (!input.title || !input.title.trim()) throw new Error("add_task needs 'title'.");
  const hire = await resolveHire(input.hire);
  const phase = input.phase ? phaseOf(input.phase) : null;
  if (input.phase && !phase) throw new Error('phase must be one of ' + PHASES.join(', ') + '.');
  const dueAt = input.dueOn ? parseDay(input.dueOn, now, 'future') : null;
  if (input.dueOn && !dueAt) throw new Error("dueOn must be a date like '2026-11-12'.");
  const title = input.title.trim();
  const existing = (await tasks.list()).find((t) => t.fields.hireId === hire.id && titleOf(t).toLowerCase() === title.toLowerCase());
  const usePhase = phase ?? (existing ? String(existing.fields.phase) : 'first week');
  const fields: Record<string, unknown> = {
    phase: usePhase,
    ...(input.owner ? { owner: input.owner.trim() } : {}),
    ...(input.note ? { notes: input.note.trim() } : {}),
    dueAt: dueAt ?? (existing && !phase ? existing.fields.dueAt : addDays(String(hire.fields.startOn), PHASE_OFFSET[usePhase])),
  };
  if (existing) {
    await tasks.update(existing.id, { fields });
    note = 'Updated the step ' + title + ' (' + existing.id + ') for ' + nameOf(hire) + '.';
  } else {
    const record = await tasks.add({ status: 'todo', fields: { hireId: hire.id, hireName: nameOf(hire), title, owner: '', ...fields } });
    note = 'Added ' + title + ' (' + record.id + ') to ' + nameOf(hire) + "'s " + usePhase + ', ' + whenText(String(record.fields.dueAt), now) + '.';
  }
  note += await settle(hire.id);
} else if (input.action === 'complete') {
  const all = await tasks.list();
  const hire = input.hire ? await resolveHire(input.hire) : null;
  const scope = all.filter((t) => (!hire || t.fields.hireId === hire.id) && (input.reopen ? t.status === 'done' : t.status !== 'done'));
  let picked: typeof all = [];
  if (input.task) {
    for (const piece of String(input.task).split(/\s*[,;]\s*/).filter(Boolean)) {
      const hits = taskMatches(scope, piece);
      if (hits.length > 1) throw new Error("More than one step matches '" + piece + "': " + hits.map((t: (typeof all)[number]) => t.id + ' ' + String(t.fields.hireName) + ': ' + titleOf(t)).join('; ') + '. Pass the id or the hire.');
      if (!hits.length) {
        const done = all.find((t) => t.id === piece.trim() || (!input.reopen && t.status === 'done' && titleOf(t).toLowerCase() === piece.trim().toLowerCase()));
        if (done && !input.reopen) continue;
        throw new Error("No open step matches '" + piece + "'" + (hire ? ' for ' + nameOf(hire) : '') + '. Open steps: ' + (scope.slice(0, 12).map((t) => t.id + ' ' + String(t.fields.hireName) + ': ' + titleOf(t)).join('; ') || 'none') + '.');
      }
      if (!picked.some((t) => t.id === hits[0].id)) picked.push(hits[0]);
    }
  } else if (input.phase) {
    const phase = phaseOf(input.phase);
    if (!phase) throw new Error('phase must be one of ' + PHASES.join(', ') + '.');
    if (!hire) throw new Error("Pass 'hire' with 'phase'.");
    picked = scope.filter((t) => t.fields.phase === phase);
  } else {
    throw new Error("complete needs 'task' (an id or words from the step) or 'hire' with 'phase'.");
  }
  for (const t of picked) {
    if (input.reopen) await tasks.transition(t.id, 'todo', input.note ? { note: input.note } : {});
    else {
      await tasks.update(t.id, { fields: { doneAt: localDay(now), ...(input.note ? { notes: input.note.trim() } : {}) } });
      await tasks.transition(t.id, 'done', input.note ? { note: input.note } : {});
    }
  }
  const hireIds = Array.from(new Set(picked.map((t) => String(t.fields.hireId))));
  note = picked.length
    ? (input.reopen ? 'Reopened ' : 'Checked off ') + picked.map((t) => String(t.fields.hireName) + ': ' + titleOf(t)).join('; ') + '.'
    : 'Nothing left to check off there.';
  for (const id of hireIds) note += await settle(id);
} else if (input.action !== 'status' && input.action !== 'list') {
  throw new Error("Unknown action '" + input.action + "'. Use status, add_hire, add_task, complete, or list.");
}

const allHires = await hires.list();
const allTasks = await tasks.list();
const view = picture(allHires, allTasks, now, withinDays);
let summary = (note ? note + ' ' : '') + view.summary;
if (input.action === 'list') {
  const wanted = input.hire ? [await resolveHire(input.hire)] : allHires;
  summary =
    wanted
      .map((h) => {
        const mine = allTasks.filter((t) => t.fields.hireId === h.id).sort((a, b) => String(a.fields.dueAt).localeCompare(String(b.fields.dueAt)));
        return (
          nameOf(h) + ' (' + h.id + ', ' + String(h.fields.role || 'no role') + ', ' + startText(h, now) + (h.status === 'done' ? ', plan complete' : '') + '):\n' +
          mine.map((t) => '[' + t.status + '] ' + String(t.fields.phase) + ': ' + taskLine(t, now)).join('\n')
        );
      })
      .join('\n\n') || 'No new hires yet.';
}
gezel.output({ active: view.active, overdue: view.overdue, dueSoon: view.dueSoon, summary });

